def _ppo_train_trace_canonical_float(text, name, nonnegative=False):
    """解析单个规范 float.hex() 字符串并返回其 float 值。"""
    if not isinstance(text, str):
        raise ValueError(f"{name} must be a canonical float.hex() str")
