        value = float.fromhex(text)
    except (ValueError, OverflowError) as exc:
        raise ValueError(
            f"{name} must be a canonical float.hex() str"
        ) from exc
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
